-- IMC-DB-001-22. Execute each target ONLY via Database Manager plan_migration/execute_migration.
-- BEFORE means inside MySQL after request arrival, before raw row persistence and all AFTER Site/report triggers.
-- Only competition_key changes. No importer or other repository changes.
-- TARGET gold; migration_id IMC-DB-001-22-gold-normalize-v1
CREATE TRIGGER `trg_GW002_results_playoff_bi` BEFORE INSERT ON `GW002_IMC Results` FOR EACH ROW SET NEW.competition_key=CASE WHEN (REGEXP_LIKE(TRIM(COALESCE(NEW.sm_action,'')), '^play[[:space:]-]*offs?$', 'i') OR REGEXP_LIKE(TRIM(COALESCE(NEW.competition_stage,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i') OR REGEXP_LIKE(TRIM(COALESCE(NEW.competition_group_name,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i') OR REGEXP_LIKE(TRIM(COALESCE(NEW.competition_round,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i')) THEN CONCAT_WS('|',NEW.game_world_id,CASE WHEN UPPER(TRIM(COALESCE(NEW.sm_country,''))) IN ('','CUS') THEN NULL ELSE UPPER(TRIM(NEW.sm_country)) END,'DOMESTIC','playoff',NULLIF(TRIM(NEW.sm_division),'')) ELSE NEW.competition_key END;

