-- TARGET custom; existing rows after DDL verified.
-- Self-assignment deliberately leaves the incoming League key intact: BEFORE UPDATE performs normalization.
UPDATE `GW001_IMC Results` SET competition_key=competition_key WHERE (REGEXP_LIKE(TRIM(COALESCE(sm_action,'')), '^play[[:space:]-]*offs?$', 'i') OR REGEXP_LIKE(TRIM(COALESCE(competition_stage,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i') OR REGEXP_LIKE(TRIM(COALESCE(competition_group_name,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i') OR REGEXP_LIKE(TRIM(COALESCE(competition_round,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i')) AND NOT(competition_key <=> CONCAT_WS('|',game_world_id,CASE WHEN UPPER(TRIM(COALESCE(sm_country,''))) IN ('','CUS') THEN NULL ELSE UPPER(TRIM(sm_country)) END,'DOMESTIC','playoff',NULLIF(TRIM(sm_division),'')));

UPDATE `GW005_IMC Results` SET competition_key=competition_key WHERE (REGEXP_LIKE(TRIM(COALESCE(sm_action,'')), '^play[[:space:]-]*offs?$', 'i') OR REGEXP_LIKE(TRIM(COALESCE(competition_stage,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i') OR REGEXP_LIKE(TRIM(COALESCE(competition_group_name,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i') OR REGEXP_LIKE(TRIM(COALESCE(competition_round,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i')) AND NOT(competition_key <=> CONCAT_WS('|',game_world_id,CASE WHEN UPPER(TRIM(COALESCE(sm_country,''))) IN ('','CUS') THEN NULL ELSE UPPER(TRIM(sm_country)) END,'DOMESTIC','playoff',NULLIF(TRIM(sm_division),'')));
